//! **Positioned v3** (`tests/fixtures/v3/<name>.json`, authoritative
//! manifest `v3/scenarios.json`):
//! [`PositionedGraphSnapshot`] generated by the current `ngrams` oracle.
//! Loaded and validated by [`load_positioned`]; there is no graph seeding for positioned fixtures.
use super::{fixtures_dir, manifest, read_json, Scenario};
pub use ngrams::output::PositionedGraphSnapshot;
use std::path::PathBuf;

/// Directory of positioned fixtures generated by the `ngrams` CLI.
pub fn positioned_dir() -> PathBuf {
    fixtures_dir().join("v3")
}

/// Authoritative positioned scenario manifest.
pub fn scenarios() -> Vec<Scenario> {
    manifest(&positioned_dir())
}

/// Load and validate a positioned fixture.
pub fn load_positioned(name: &str) -> PositionedGraphSnapshot {
    let path = positioned_dir().join(format!("{name}.json"));
    let fixture: PositionedGraphSnapshot = read_json(&path);
    fixture
        .validate()
        .unwrap_or_else(|error| panic!("{}: invalid positioned fixture: {error}", path.display()));
    fixture
}
